def incorporar_historial(apps, schema_editor):
    Envio = apps.get_model("Gesicom", "Envio")
    Movimiento = apps.get_model("Gesicom", "MovimientoEvidencia")
    alias = schema_editor.connection.alias
    lote = []
    for envio in Envio.objects.using(alias).only("pk", "version", "aprobada", "rechazada").iterator(chunk_size=500):
        estado = "aprobada" if envio.aprobada else "rechazada" if envio.rechazada else "pendiente"
        lote.append(
            Movimiento(
                envio_id=envio.pk,
                version=envio.version,
                accion="historico",
                estado=estado,
                detalle="Estado existente al activar el historial. Las revisiones anteriores no tenían seguimiento individual.",
            )
        )
        if len(lote) == 500:
            Movimiento.objects.using(alias).bulk_create(lote, batch_size=500, ignore_conflicts=True)
            lote = []
    if lote:
        Movimiento.objects.using(alias).bulk_create(lote, batch_size=500, ignore_conflicts=True)


